from typing import Any, Callable, Optional, Type
from .logger.logger import logger
from .astribot_ros_middleware import get_ros_version


class Node:
    """统一的ROS节点封装类，自动适配ROS1和ROS2"""

    def __init__(self, node_name: str, **kwargs):
        """初始化节点，自动检测ROS版本并创建对应实现"""
        self.node_name = node_name
        self._ros_version = get_ros_version()

        if self._ros_version == 1:
            from .ros1 import ROS1Node

            self._node = ROS1Node(node_name, **kwargs)
        elif self._ros_version == 2:
            from .ros2 import ROS2Node

            self._node = ROS2Node(node_name, **kwargs)
        else:
            raise RuntimeError(f"不支持的ROS版本: {self._ros_version}")

    def create_publisher(
        self, msg_type: Type, topic: str, qos_profile: int = 10, **kwargs
    ):
        """创建发布者

        Args:
            msg_type: 消息类型
            topic: 话题名称
            qos_profile: QoS配置（ROS1为queue_size，ROS2为QoS profile）
        """
        return self._node.create_publisher(msg_type, topic, qos_profile, **kwargs)

    def create_subscriber(
        self,
        msg_type: Type,
        topic: str,
        callback: Callable,
        qos_profile: int = 10,
        **kwargs,
    ):
        """创建订阅者

        Args:
            msg_type: 消息类型
            topic: 话题名称
            callback: 回调函数
            qos_profile: QoS配置（ROS1为queue_size，ROS2为QoS profile）
        """
        return self._node.create_subscriber(
            msg_type, topic, callback, qos_profile, **kwargs
        )

    def create_service(
        self, srv_type: Type, service_name: str, callback: Callable, **kwargs
    ):
        """创建服务端

        Args:
            srv_type: 服务类型
            service_name: 服务名称
            callback: 回调函数
        """
        return self._node.create_service(srv_type, service_name, callback, **kwargs)

    def create_client(self, srv_type: Type, service_name: str, **kwargs):
        """创建服务客户端

        Args:
            srv_type: 服务类型
            service_name: 服务名称
        """
        return self._node.create_client(srv_type, service_name, **kwargs)

    def wait_for_service(self, service_name: str, timeout: Optional[float] = None):
        """等待服务可用

        Args:
            service_name: 服务名称
            timeout: 超时时间（秒），None表示无限等待

        Returns:
            服务是否可用（ROS2返回bool，ROS1无返回值）
        """
        return self._node.wait_for_service(service_name, timeout)

    def declare_parameter(self, name: str, value: Any = None, **kwargs):
        """声明参数

        Args:
            name: 参数名称
            value: 参数值
        """
        return self._node.declare_parameter(name, value, **kwargs)

    def get_parameter(
        self, name: str, default: Any = None, node_name: Optional[str] = None
    ):
        """获取参数

        Args:
            name: 参数名称
            default: 默认值
            node_name: 节点名称，如果指定则获取其他节点的参数，否则获取当前节点的参数
        """
        return self._node.get_parameter(name, default, node_name)

    def set_parameter(self, name: str, value: Any):
        """设置参数

        Args:
            name: 参数名称
            value: 参数值
        """
        return self._node.set_parameter(name, value)

    def has_parameter(self, name: str) -> bool:
        """检查参数是否存在

        Args:
            name: 参数名称
        """
        return self._node.has_parameter(name)

    def create_timer(self, period: float, callback: Callable):
        """创建定时器

        Args:
            period: 定时器周期（秒）
            callback: 回调函数
        """
        return self._node.create_timer(period, callback)

    def get_logger(self):
        """获取日志器"""
        return logger

    def spin(self):
        """开始节点循环"""
        return self._node.spin()

    def destroy_node(self):
        """销毁节点"""
        if hasattr(self._node, "destroy_node"):
            self._node.destroy_node()


__all__ = ["Node", "get_ros_version"]
